(() => {
 const root=document.documentElement, reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover: hover) and (pointer: fine)');
 const button=document.createElement('button');button.className='motion-toggle';button.type='button';button.setAttribute('aria-pressed','false');button.textContent='إيقاف الحركة Ⅱ';
 const footer=document.querySelector('footer'),container=document.createElement('div');container.className='footer-actions';container.append(button,footer.lastElementChild);footer.append(container);
 let manualOff=false;try{manualOff=localStorage.getItem('murooj-motion')==='off'}catch{}
 const enabled=()=>!manualOff&&!reduced.matches;
 function sync(){root.dataset.motion=enabled()?'on':'off';button.textContent=enabled()?'إيقاف الحركة Ⅱ':'تشغيل الحركة ▷';button.setAttribute('aria-pressed',String(!enabled()));if(!enabled()){root.classList.remove('pointer-ready');root.style.removeProperty('--visual-x');root.style.removeProperty('--visual-y')}}
 button.addEventListener('click',()=>{manualOff=!manualOff;try{localStorage.setItem('murooj-motion',manualOff?'off':'on')}catch{}sync()});reduced.addEventListener('change',sync);sync();
 document.querySelectorAll('.practice-list article,.skill-row,.course-row,.tech-tags span').forEach((el,i)=>el.style.setProperty('--reveal-delay',`${i%3*80}ms`));
 const visual=document.querySelector('.identity-visual'),hero=document.querySelector('.hero'),journey=document.querySelector('.timeline'),arts=[...document.querySelectorAll('.project-art')];
 let pointerFrame=0,clientX=0,clientY=0;
 document.addEventListener('pointermove',e=>{if(!fine.matches||!enabled()||e.pointerType==='touch')return;clientX=e.clientX;clientY=e.clientY;if(pointerFrame)return;pointerFrame=requestAnimationFrame(()=>{root.style.setProperty('--cursor-x',clientX+'px');root.style.setProperty('--cursor-y',clientY+'px');root.classList.add('pointer-ready');const rect=hero.getBoundingClientRect();if(rect.bottom>0){root.style.setProperty('--visual-x',((clientX/innerWidth-.5)*24)+'px');root.style.setProperty('--visual-y',((clientY/innerHeight-.5)*18)+'px')}pointerFrame=0})},{passive:true});
 document.addEventListener('pointerout',e=>{if(!e.relatedTarget)root.classList.remove('pointer-ready')});
 document.querySelectorAll('a,button,summary').forEach(el=>{el.addEventListener('pointerenter',()=>root.classList.add('pointer-active'));el.addEventListener('pointerleave',()=>root.classList.remove('pointer-active'))});
 arts.forEach(art=>{let frame=0;art.addEventListener('pointermove',e=>{if(!fine.matches||!enabled()||frame)return;const x=e.clientX,y=e.clientY;frame=requestAnimationFrame(()=>{const r=art.getBoundingClientRect(),px=(x-r.left)/r.width,py=(y-r.top)/r.height;art.style.setProperty('--mx',px*100+'%');art.style.setProperty('--my',py*100+'%');art.style.setProperty('--tilt-x',((.5-py)*9)+'deg');art.style.setProperty('--tilt-y',((px-.5)*10)+'deg');frame=0})});art.addEventListener('pointerleave',()=>{art.style.setProperty('--tilt-x','0deg');art.style.setProperty('--tilt-y','0deg')})});
 document.querySelectorAll('.magnetic').forEach(el=>{el.addEventListener('pointermove',e=>{if(!fine.matches||!enabled())return;const r=el.getBoundingClientRect();el.style.setProperty('--magnet-x',(e.clientX-r.left-r.width/2)*.12+'px');el.style.setProperty('--magnet-y',(e.clientY-r.top-r.height/2)*.2+'px')});el.addEventListener('pointerleave',()=>{el.style.setProperty('--magnet-x','0px');el.style.setProperty('--magnet-y','0px')})});
 let scrollFrame=0;function update(){if(journey){const r=journey.getBoundingClientRect(),progress=Math.min(1,Math.max(0,(innerHeight*.65-r.top)/r.height));journey.style.setProperty('--journey-progress',String(progress))}if(enabled())arts.forEach(art=>{const r=art.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)art.style.setProperty('--art-shift',Math.max(-25,Math.min(25,(innerHeight/2-r.top-r.height/2)*.06))+'px')});scrollFrame=0}addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(update)},{passive:true});addEventListener('resize',update);update();
})();
